const works=[{title:'A Fold in Time',type:'fold',style:'one',description:'A single diagonal crease turns a flat plane into a quiet study of light and shadow. A small gesture, held in place.'},{title:'A Place for Light',type:'cut',style:'two',description:'A circular opening invites the space behind it to become part of the work. What is removed can be just as expressive as what remains.'},{title:'The Color Between',type:'layer',style:'three',description:'Layers of bright paper meet at unexpected angles, allowing simple shapes to find an entirely new rhythm together.'},{title:'Almost a Flower',type:'fold',style:'four',description:'Two folded forms lean toward each other, suggesting petals without quite becoming them. An exercise in seeing possibility.'}];const gallery=document.querySelector('#gallery');const dialog=document.querySelector('#detail');let lastFocus;function render(filter='all'){gallery.innerHTML=works.map((w,i)=>({w,i})).filter(({w})=>filter==='all'||w.type===filter).map(({w,i})=>`<button class="work" data-work="${i}" aria-label="View ${w.title}"><div class="art ${w.style}" aria-hidden="true"><div class="sculpture"></div></div><div class="work-meta"><div><h3>${w.title}</h3><p>${w.type} / Paper study</p></div><span class="plus" aria-hidden="true">+</span></div></button>`).join('')}document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');render(button.dataset.filter)}));gallery.addEventListener('click',e=>{const button=e.target.closest('[data-work]');if(!button)return;lastFocus=button;const w=works[button.dataset.work];document.querySelector('#dialogTitle').textContent=w.title;document.querySelector('#dialogType').textContent=w.type.toUpperCase()+' / PAPER STUDY';document.querySelector('#dialogText').textContent=w.description;document.querySelector('#dialogArt').className='dialog-art art '+w.style;document.querySelector('#dialogArt').innerHTML='<div class="sculpture"></div>';dialog.showModal()});dialog.addEventListener('close',()=>lastFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});render();
